    "hi": {"workspaceTitle":"इस संसाधन पर कौन काम कर रहा है?","workspaceDescription":"साझा डिवाइस पर अपने-आप सहेजे गए उत्तरों और टिप्पणियों को अलग रखने के लिए कोई नाम या उपनाम लिखें। आप इस ब्राउज़र में अपना काम सहेजे बिना इस संसाधन का एक बार उपयोग भी कर सकते हैं।","nameLabel":"नाम या उपनाम","continueAutosave":"अपने-आप सहेजने के साथ जारी रखें","useOnce":"बिना सहेजे एक बार उपयोग करें","requiredName":"कोई नाम या उपनाम लिखें।","oneTimeNotice":"एक बार का सत्र: ब्राउज़र में अपने-आप सहेजना बंद है। आप अब भी अपने उत्तर और टिप्पणियाँ डाउनलोड कर सकते हैं।","saveWorkTitle":"अपना काम सहेजें","saveWorkDescription":"कोई नाम या उपनाम लिखें ताकि आपके शिक्षक इस जमा किए गए काम को पहचान सकें।","saveWorkConfirm":"काम सहेजें","saveAnswersTitle":"अपने उत्तर सहेजें","saveAnswersDescription":"कोई नाम या उपनाम लिखें ताकि आपके शिक्षक इस उत्तर फ़ाइल को पहचान सकें।","saveAnswersConfirm":"उत्तर सहेजें","cancel":"रद्द करें","saveMyAnswers":"मेरे उत्तर सहेजें","savedAnswers":"सहेज लिया गया! फ़ाइल अपने शिक्षक को भेजें","saveErrorPrefix":"आपके उत्तर सहेजे नहीं जा सके: ","saveToolsLabel":"अपना काम सहेजें और जमा करें","doneTitle":"क्या आपका काम पूरा हो गया?","answerFileDescription":"अपने उत्तरों की एक फ़ाइल सहेजें और उसे अपने शिक्षक को भेजें।","answerFileHelp":"एक .json फ़ाइल सहेजता है, जिसे आपके शिक्षक AlloFlow में खोलते हैं।","encryptedMailboxDescription":"अपना एन्क्रिप्ट किया गया काम सीधे अपने शिक्षक के कक्षा मेलबॉक्स में भेजें। अगर भेजना विफल हो जाए, तो उसकी जगह एक एन्क्रिप्ट की गई फ़ाइल डाउनलोड होगी।","encryptedFileDescription":"अपने उत्तरों वाली एक एन्क्रिप्ट की गई फ़ाइल सहेजें और उसे अपने शिक्षक को भेजें।","encryptionHelp":"आपके उत्तर आपकी कक्षा की कुंजी से एन्क्रिप्ट किए जाते हैं। केवल आपके शिक्षक ही उन्हें खोल सकते हैं।","saveMyWork":"मेरा काम सहेजें","saving":"सहेजा जा रहा है…","savedDownload":"सहेज लिया गया — डाउनलोड शुरू हो गया","saveAgain":"मेरा काम फिर से सहेजें","saveUnavailable":"सहेजना उपलब्ध नहीं है (कुंजी नहीं मिली)","encryptionUnavailable":"इस ब्राउज़र में एन्क्रिप्शन उपलब्ध नहीं है। जमा किया जाने वाला काम सहेजने के लिए किसी नए ब्राउज़र का उपयोग करें।","sending":"आपके शिक्षक को भेजा जा रहा है…","sent":"आपके शिक्षक को भेज दिया गया","sentToTeacher":"आपका एन्क्रिप्ट किया गया काम आपके शिक्षक को भेज दिया गया","sendAgain":"मेरा काम फिर से भेजें","mailboxFallback":"आपके शिक्षक के कक्षा मेलबॉक्स तक नहीं पहुँच सके। इसकी जगह एक एन्क्रिप्ट की गई फ़ाइल डाउनलोड होगी; वह फ़ाइल अपने शिक्षक को भेजें।","workSaveErrorPrefix":"आपका काम सहेजा नहीं जा सका: ","skipToContent":"सामग्री पर जाएँ","readingToolsLabel":"पढ़ने और टिप्पणी करने के टूल","toolsLabel":"टूल","accessibilityInfoLabel":"सुलभता की जानकारी","accessibilityTitle":"सुलभता सुविधाएँ","accessibilityDescription":"इस दस्तावेज़ में अर्थपूर्ण संरचना, शीर्षकों का क्रम, तालिका शीर्षक, लैंडमार्क, भाषा मेटाडेटा, तार्किक पठन क्रम और प्रिंट के लिए अनुकूलित लेआउट शामिल हैं। यह स्वतंत्र रूप से सत्यापित WCAG या PDF/UA अनुरूपता का दावा नहीं है; अनुपालन के लिए इस पर भरोसा करने से पहले किसी सुलभता जाँच टूल से इसकी जाँच करें। AlloFlow से बनाया गया।","submissionFor":"{name} का जमा किया गया काम","worksheetLabel":"वर्कशीट","savedLabel":"सहेजा गया","encryptedClassKey":"कक्षा कुंजी से एन्क्रिप्ट किया गया","encryptedFileHelp":"इस फ़ाइल में एन्क्रिप्ट किए गए उत्तर हैं। इसे डिक्रिप्ट करने के लिए, मेल खाने वाली कक्षा कुंजी फ़ाइल के साथ इसे AlloFlow (दस्तावेज़ बिल्डर → जमा किया गया काम आयात करें) में खोलें।","resourceIdLabel":"संसाधन आईडी","printLinksTitle":"इस संसाधन के वेब लिंक","readAloudUnavailable":"इस अनुच्छेद के लिए पढ़कर सुनाने वाला ऑडियो उपलब्ध नहीं था। अनुच्छेद का पाठ अब भी नीचे उपलब्ध है।","readAloudPartial":"{total} में से {ready} वाक्यों के लिए ऑडियो उपलब्ध है। बाकी हिस्सों के लिए पाठ पढ़ें।"},
