    "yo": {"workspaceTitle":"Ta ló ń ṣiṣẹ́ lórí ohun èlò yìí?","workspaceDescription":"Tẹ orúkọ tàbí orúkọ ìnagijẹ kí àwọn ìdáhùn àti àkọsílẹ̀ tí a fi pamọ́ fúnra rẹ̀ lè wà lọ́tọ̀ọ̀tọ̀ lórí ẹ̀rọ tí ọ̀pọ̀ ènìyàn ń lò papọ̀. O tún lè lo ohun èlò yìí lẹ́ẹ̀kan ṣoṣo láìfi iṣẹ́ rẹ pamọ́ sínú aṣàwákiri yìí.","nameLabel":"Orúkọ tàbí orúkọ ìnagijẹ","continueAutosave":"Tẹ̀síwájú pẹ̀lú ìfipamọ́ aládàáṣe","useOnce":"Lò ó lẹ́ẹ̀kan láìsí ìfipamọ́ aládàáṣe","requiredName":"Tẹ orúkọ tàbí orúkọ ìnagijẹ.","oneTimeNotice":"Ìgbà lílò ẹ̀ẹ̀kan: ìfipamọ́ aládàáṣe aṣàwákiri ti wà ní pípa. O ṣì lè ṣe ìgbàsílẹ̀ àwọn ìdáhùn àti àkọsílẹ̀ rẹ.","saveWorkTitle":"Fi iṣẹ́ rẹ pamọ́","saveWorkDescription":"Tẹ orúkọ tàbí orúkọ ìnagijẹ kí olùkọ́ rẹ lè mọ ẹni tó fi iṣẹ́ yìí sílẹ̀.","saveWorkConfirm":"Fi iṣẹ́ pamọ́","saveAnswersTitle":"Fi àwọn ìdáhùn rẹ pamọ́","saveAnswersDescription":"Tẹ orúkọ tàbí orúkọ ìnagijẹ kí olùkọ́ rẹ lè mọ ẹni tó ni fáìlì ìdáhùn yìí.","saveAnswersConfirm":"Fi àwọn ìdáhùn pamọ́","cancel":"Fagilé","saveMyAnswers":"Fi àwọn ìdáhùn mi pamọ́","savedAnswers":"A ti fi pamọ́! Fi fáìlì náà ránṣẹ́ sí olùkọ́ rẹ","saveErrorPrefix":"A kò lè fi àwọn ìdáhùn rẹ pamọ́: ","saveToolsLabel":"Fi iṣẹ́ rẹ pamọ́ kí o sì fi í sílẹ̀","doneTitle":"Ṣé o ti parí iṣẹ́ rẹ?","answerFileDescription":"Fi fáìlì àwọn ìdáhùn rẹ pamọ́ kí o sì fi ránṣẹ́ sí olùkọ́ rẹ.","answerFileHelp":"Ó máa fi fáìlì .json kan pamọ́ tí olùkọ́ rẹ yóò ṣí nínú AlloFlow.","encryptedMailboxDescription":"Fi iṣẹ́ rẹ tí a ti tì pa ránṣẹ́ tààrà sí àpótí lẹ́tà kíláàsì olùkọ́ rẹ. Bí fífiránṣẹ́ bá kùnà, a ó ṣe ìgbàsílẹ̀ fáìlì tí a ti tì pa dípò rẹ̀.","encryptedFileDescription":"Fi fáìlì tí a ti tì pa tí ó ní àwọn ìdáhùn rẹ pamọ́ kí o sì fi ránṣẹ́ sí olùkọ́ rẹ.","encryptionHelp":"A ti fi kọ́kọ́rọ́ kíláàsì tì àwọn ìdáhùn rẹ pa. Olùkọ́ rẹ nìkan ló lè ṣí wọn.","saveMyWork":"Fi iṣẹ́ mi pamọ́","saving":"Ó ń fi pamọ́…","savedDownload":"A ti fi pamọ́ — ìgbàsílẹ̀ ti bẹ̀rẹ̀","saveAgain":"Tún fi iṣẹ́ mi pamọ́","saveUnavailable":"Kò ṣeé fi pamọ́ (kọ́kọ́rọ́ kò sí)","encryptionUnavailable":"Títì iṣẹ́ pa pẹ̀lú kọ́kọ́rọ́ kò ṣeé ṣe nínú aṣàwákiri yìí. Lo aṣàwákiri tuntun láti fi iṣẹ́ tí o fẹ́ fi sílẹ̀ pamọ́.","sending":"Ó ń fi ránṣẹ́ sí olùkọ́ rẹ…","sent":"A ti fi ránṣẹ́ sí olùkọ́ rẹ","sentToTeacher":"A ti fi iṣẹ́ rẹ tí a tì pa ránṣẹ́ sí olùkọ́ rẹ","sendAgain":"Tún fi iṣẹ́ mi ránṣẹ́","mailboxFallback":"A kò lè dé àpótí lẹ́tà kíláàsì olùkọ́ rẹ. A ó ṣe ìgbàsílẹ̀ fáìlì tí a tì pa dípò rẹ̀; fi fáìlì náà ránṣẹ́ sí olùkọ́ rẹ.","workSaveErrorPrefix":"A kò lè fi iṣẹ́ rẹ pamọ́: ","skipToContent":"Fò sí àkóónú","readingToolsLabel":"Àwọn irinṣẹ́ kíkà àti àkọsílẹ̀","toolsLabel":"Àwọn irinṣẹ́","accessibilityInfoLabel":"Ìwífún nípa ìráyèsí","accessibilityTitle":"Àwọn ẹ̀yà ìráyèsí","accessibilityDescription":"Ìwé yìí ní ètò ìtumọ̀ (semantic structure), ìtòlẹ́sẹẹsẹ àwọn àkọlé, àwọn àkọlé tábìlì, àwọn àmì agbègbè (landmarks), ìwífún nípa èdè, ètò kíkà tó bọ́gbọ́n mu, àti ìṣètò tí a ṣe fún títẹ̀ jáde. Èyí kì í ṣe ìkéde ìbámu pẹ̀lú WCAG tàbí PDF/UA tí àjọ olómìnira kan ti fìdí rẹ̀ múlẹ̀; ṣàyẹ̀wò rẹ̀ pẹ̀lú irinṣẹ́ àyẹ̀wò ìráyèsí kí o tó gbẹ́kẹ̀lé e gẹ́gẹ́ bí ẹ̀rí ìbámu. A ṣẹ̀dá rẹ̀ pẹ̀lú AlloFlow.","submissionFor":"Iṣẹ́ tí {name} fi sílẹ̀","worksheetLabel":"Ìwé iṣẹ́","savedLabel":"A ti fi pamọ́","encryptedClassKey":"A ti fi kọ́kọ́rọ́ kíláàsì tì í pa","encryptedFileHelp":"Fáìlì yìí ní àwọn ìdáhùn tí a ti tì pa. Ṣí i nínú AlloFlow (Olùṣẹ̀dá Ìwé → Gbé iṣẹ́ tí a fi sílẹ̀ wọlé) pẹ̀lú fáìlì kọ́kọ́rọ́ kíláàsì tó bá a mu láti ṣí i.","resourceIdLabel":"Nọ́mbà ìdánimọ̀ ohun èlò","printLinksTitle":"Àwọn ìjápọ̀ wẹ́ẹ̀bù fún ohun èlò yìí","readAloudUnavailable":"Ohùn kíkà sókè kò sí fún àyọkà yìí. Ọ̀rọ̀ àyọkà náà ṣì wà nísàlẹ̀.","readAloudPartial":"Ohùn wà fún gbólóhùn {ready} nínú {total}. Ka ọ̀rọ̀ náà fún àwọn apá tí kò ní ohùn."},
